_r_car = int(np.where(ng4 == GI_CARRIER)[0][0]) + 1
_r_319 = int(np.where(ng4 == int(ng_desc[25]))[0][0]) + 1
assert _r_car == F4["carrier_rank"] == 21, (_r_car, "f4 carrier rank")
