assert round(_jac4, 4) == F4["jaccard_heavy"] == 0.9231, _jac4
assert int((emask_n & pm4).sum()) == F4["closure_edges"] == 472095
assert int((emask_wA & pm4).sum()) == F4["wA_edges"] == 469256
